        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.SHORT;
        TimeZone tz = TimeZone.getDefault();

        FastDateFormat formatUS = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, Locale.US);
